var i=`0790-ladob`;var t=`world-0790`;var a=`SC`;var s=`eastern-africa`;var r=4;var o=40;var d={en:`Ladob`,ua:`Ладоб`};var l={en:`Ladob is a Seychelles classic prepared with plantain, coconut milk, desiccated coconut. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Ладоб, страва кухні країни Сейшельські Острови зі складниками: плантан, кокосове молоко, кокосова стружка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`plantain`,620,`g`],[`coconut-milk`,420,`ml`],[`water`,250,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 15 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 15 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:15,i:[[`white-granulated-sugar`,70,`g`],[`ground-nutmeg`,3,`g`],[`ground-cinnamon`,3,`g`],[`vanilla-extract`,5,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`desiccated-coconut`,45,`g`]]}];var u={slug:i,id:t,country:`SC`,region:s,servings:4,minutes:40,title:d,text:l,steps:g};export{a as country,u as default,t as id,o as minutes,s as region,r as servings,i as slug,g as steps,l as text,d as title};